DECLARE @N TABLE(n INT PRIMARY KEY);
INSERT @N SELECT TOP (100) ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) FROM sys.all_objects a CROSS JOIN sys.all_objects b;

INSERT Aziende(Codice,RagioneSociale,PartitaIVA,Provincia,Settore,FatturatoAnnuale)
SELECT CONCAT('AZ',FORMAT(n,'000')),CONCAT(N'Industria Italia ',n),RIGHT('00000000000'+CAST(10000000000+n AS VARCHAR(11)),11),CHOOSE((n-1)%10+1,'BO','MO','RE','MI','TO','PD','VR','FI','RM','AN'),CHOOSE((n-1)%6+1,N'Meccanica',N'Automazione',N'Automotive',N'Elettronica',N'Alimentare',N'Plastica'),CAST(750000+n*37500 AS DECIMAL(18,2)) FROM @N;
INSERT Sedi(AziendaId,Descrizione,Indirizzo,CAP,Comune,Provincia) SELECT n,CONCAT(N'Sede principale ',n),CONCAT(N'Via dell''Industria ',n),FORMAT(40000+n,'00000'),CHOOSE((n-1)%8+1,N'Bologna',N'Modena',N'Reggio Emilia',N'Milano',N'Torino',N'Padova',N'Verona',N'Firenze'),CHOOSE((n-1)%8+1,'BO','MO','RE','MI','TO','PD','VR','FI') FROM @N;
INSERT Reparti(AziendaId,Codice,Nome) SELECT ((n-1)%100)+1,CONCAT('REP',FORMAT(n,'000')),CHOOSE((n-1)%8+1,N'Produzione',N'Acquisti',N'Vendite',N'Logistica',N'Qualità',N'Amministrazione',N'IT',N'R&D') FROM @N;
INSERT CentriCosto(AziendaId,Codice,Descrizione,RepartoId) SELECT ((n-1)%100)+1,CONCAT('CC',FORMAT(n,'000')),CONCAT(N'Centro costo ',n),n FROM @N;
INSERT Dipendenti(AziendaId,RepartoId,Nome,Cognome,Email,DataAssunzione,Qualifica,CostoOrario) SELECT ((n-1)%100)+1,n,CHOOSE((n-1)%10+1,N'Marco',N'Anna',N'Paolo',N'Laura',N'Giulia',N'Luca',N'Sara',N'Andrea',N'Elena',N'Davide'),CHOOSE((n-1)%10+1,N'Rossi',N'Bianchi',N'Verdi',N'Ferrari',N'Romano',N'Esposito',N'Colombo',N'Ricci',N'Marino',N'Greco'),CONCAT('dipendente',n,'@industriaitalia.test'),DATEADD(DAY,-n*17,CAST('2026-09-01' AS DATE)),CHOOSE((n-1)%6+1,N'Operatore',N'Tecnico',N'Impiegato',N'Buyer',N'Analista',N'Responsabile'),25+n%25 FROM @N;
INSERT Agenti(AziendaId,Codice,Nome,Cognome,Zona,PercentualeProvvigione) SELECT ((n-1)%100)+1,CONCAT('AG',FORMAT(n,'000')),CHOOSE((n-1)%5+1,N'Andrea',N'Federico',N'Chiara',N'Matteo',N'Valentina'),CHOOSE((n-1)%5+1,N'Costa',N'Conti',N'Ferrari',N'Gallo',N'Fontana'),CHOOSE((n-1)%5+1,N'Nord',N'Centro',N'Sud',N'Nord-Est',N'Export'),2.5+(n%5)*0.5 FROM @N;
INSERT Clienti(AziendaId,Codice,RagioneSociale,PartitaIVA,Citta,Provincia,Segmento,Fido,AgenteId) SELECT ((n-1)%100)+1,CONCAT('CLI',FORMAT(n,'000')),CONCAT(N'Cliente Industriale ',n),RIGHT('00000000000'+CAST(20000000000+n AS VARCHAR(11)),11),CHOOSE((n-1)%8+1,N'Bologna',N'Modena',N'Reggio Emilia',N'Milano',N'Torino',N'Padova',N'Verona',N'Parma'),CHOOSE((n-1)%8+1,'BO','MO','RE','MI','TO','PD','VR','PR'),CHOOSE((n-1)%4+1,N'Industria',N'Distribuzione',N'Automotive',N'Export'),10000+n*250,((n-1)%100)+1 FROM @N;
INSERT Fornitori(AziendaId,Codice,RagioneSociale,PartitaIVA,Citta,Provincia,Categoria,Fido) SELECT ((n-1)%100)+1,CONCAT('FOR',FORMAT(n,'000')),CONCAT(N'Fornitore Tecnico ',n),RIGHT('00000000000'+CAST(30000000000+n AS VARCHAR(11)),11),CHOOSE((n-1)%6+1,N'Bologna',N'Modena',N'Reggio Emilia',N'Milano',N'Vicenza',N'Brescia'),CHOOSE((n-1)%6+1,'BO','MO','RE','MI','VI','BS'),CHOOSE((n-1)%4+1,N'Materie prime',N'Componenti',N'Servizi',N'Packaging'),15000+n*150 FROM @N;
INSERT Vettori(AziendaId,Codice,RagioneSociale,Provincia,CostoMedioSpedizione) SELECT ((n-1)%100)+1,CONCAT('VET',FORMAT(n,'000')),CONCAT(N'Logistica Express ',n),CHOOSE((n-1)%5+1,'BO','MO','MI','PD','VR'),35+n%40 FROM @N;
INSERT Banche(AziendaId,CodiceABI,Nome,Provincia) SELECT ((n-1)%100)+1,FORMAT(30000+n,'00000'),CONCAT(N'Banca Impresa ',n),CHOOSE((n-1)%5+1,'BO','MO','MI','PD','RM') FROM @N;
INSERT CategorieArticolo(Codice,Descrizione,Famiglia) SELECT CONCAT('CAT',FORMAT(n,'000')),CHOOSE((n-1)%6+1,N'Materie prime',N'Componenti meccanici',N'Elettronica',N'Semilavorati',N'Prodotti finiti',N'Imballaggi'),CHOOSE((n-1)%4+1,N'Produzione',N'Acquisti',N'Vendita',N'Logistica') FROM @N;
INSERT UnitaMisura(Codice,Descrizione,FattoreConversione) SELECT CONCAT('UM',FORMAT(n,'000')),CHOOSE((n-1)%5+1,N'Pezzo',N'Chilogrammo',N'Metro',N'Litro',N'Ora'),1 FROM @N;
INSERT Articoli(Codice,Descrizione,CategoriaId,UnitaMisuraId,CostoStandard,PrezzoVendita,PesoKg,TipoArticolo,ScortaMinima) SELECT CONCAT('ART',FORMAT(n,'00000')),CONCAT(CHOOSE((n-1)%5+1,N'Motore',N'Sensore',N'Valvola',N'Pannello',N'Gruppo'),N' industriale ',n),((n-1)%100)+1,((n-1)%100)+1,25+n*3.75,45+n*6.50,0.25+(n%30)*0.1,CHOOSE((n-1)%3+1,'MATERIALE','SEMILAVORATO','FINITO'),5+n%25 FROM @N;
INSERT Magazzini(AziendaId,Codice,Descrizione,Comune,Provincia) SELECT ((n-1)%100)+1,CONCAT('MAG',FORMAT(n,'000')),CONCAT(N'Magazzino ',n),CHOOSE((n-1)%5+1,N'Bologna',N'Modena',N'Reggio Emilia',N'Milano',N'Padova'),CHOOSE((n-1)%5+1,'BO','MO','RE','MI','PD') FROM @N;
INSERT Ubicazioni(MagazzinoId,Codice,Corsia,Scaffale,Piano) SELECT n,CONCAT('UB',FORMAT(n,'000')),CONCAT('C',((n-1)%20)+1),CONCAT('S',((n-1)%10)+1),((n-1)%5)+1 FROM @N;
INSERT Listini(Codice,Descrizione,Valuta,DataValiditaDal,DataValiditaAl) SELECT CONCAT('LIS',FORMAT(n,'000')),CONCAT(N'Listino ',n),'EUR','2026-01-01','2026-12-31' FROM @N;
INSERT ListiniRighe(ListinoId,ArticoloId,Prezzo,ScontoPercentuale,QuantitaMinima) SELECT n,n,45+n*6.5,n%15,n%20+1 FROM @N;
INSERT CondizioniPagamento(Codice,Descrizione,GiorniScadenza,NumeroRate) SELECT CONCAT('PAG',FORMAT(n,'000')),CONCAT(N'Pagamento ',n),n%120,n%4+1 FROM @N;
INSERT AliquoteIVA(Codice,Descrizione,Percentuale) SELECT CONCAT('IVA',FORMAT(n,'000')),CONCAT(N'Aliquota ',n),CHOOSE((n-1)%4+1,4,5,10,22) FROM @N;
INSERT CausaliMagazzino(Codice,Descrizione,Segno) SELECT CONCAT('CAU',FORMAT(n,'000')),CHOOSE((n-1)%4+1,N'Carico acquisto',N'Scarico vendita',N'Carico produzione',N'Scarico produzione'),CHOOSE((n-1)%4+1,1,-1,1,-1) FROM @N;
INSERT MovimentiMagazzino(DataMovimento,ArticoloId,MagazzinoId,UbicazioneId,CausaleId,Quantita,CostoUnitario,Documento) SELECT DATEADD(DAY,-n%365,'2026-09-01'),n,n,n,n,50+n%100,25+n*3.75,CONCAT('MOV-',FORMAT(n,'000000')) FROM @N;
INSERT Lotti(CodiceLotto,ArticoloId,DataProduzione,DataScadenza,Quantita) SELECT CONCAT('LOT-',FORMAT(n,'000000')),n,DATEADD(DAY,-n,'2026-09-01'),DATEADD(DAY,365-n%90,'2026-09-01'),100+n FROM @N;
INSERT Seriali(CodiceSeriale,ArticoloId,Stato,DataCarico) SELECT CONCAT('SN-',FORMAT(n,'000000')),n,CHOOSE((n-1)%4+1,'DISPONIBILE','ASSEGNATO','VENDUTO','IN_RIPARAZIONE'),DATEADD(DAY,-n,'2026-09-01') FROM @N;
INSERT OrdiniClienti(NumeroOrdine,DataOrdine,ClienteId,AgenteId,Stato,TotaleNetto,TotaleIVA,TotaleDocumento) SELECT CONCAT('OC-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%240,'2026-09-01'),n,n,CHOOSE((n-1)%4+1,'EVASO','APERTO','PARZIALE','ANNULLATO'),1000+n*75,1000+n*75*.22,1000+n*75*1.22 FROM @N;
INSERT RigheOrdineCliente(OrdineClienteId,NumeroRiga,ArticoloId,Quantita,PrezzoUnitario,ScontoPercentuale,ImportoNetto) SELECT n,1,n,5+n%20,45+n*6.5,n%10,(5+n%20)*(45+n*6.5)*(1-(n%10)/100.0) FROM @N;
INSERT DDTClienti(NumeroDDT,DataDDT,ClienteId,OrdineClienteId,VettoreId,TotaleQuantita) SELECT CONCAT('DDTC-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%200,'2026-09-01'),n,n,n,5+n%20 FROM @N;
INSERT RigheDDTCliente(DDTClienteId,ArticoloId,Quantita) SELECT n,n,5+n%20 FROM @N;
INSERT FattureClienti(NumeroFattura,DataFattura,ClienteId,OrdineClienteId,Imponibile,IVA,Totale,Stato) SELECT CONCAT('FC-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%180,'2026-09-01'),n,n,1000+n*75,(1000+n*75)*.22,(1000+n*75)*1.22,CHOOSE((n-1)%3+1,'PAGATA','APERTA','PARZIALE') FROM @N;
INSERT RigheFatturaCliente(FatturaClienteId,ArticoloId,AliquotaIVAId,Quantita,PrezzoUnitario,ScontoPercentuale,Imponibile) SELECT n,n,n,5+n%20,45+n*6.5,n%10,(5+n%20)*(45+n*6.5)*(1-(n%10)/100.0) FROM @N;
INSERT OrdiniFornitori(NumeroOrdine,DataOrdine,FornitoreId,Stato,TotaleNetto,TotaleIVA,TotaleDocumento) SELECT CONCAT('OF-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%240,'2026-09-01'),n,CHOOSE((n-1)%3+1,'EVASO','APERTO','PARZIALE'),700+n*50,(700+n*50)*.22,(700+n*50)*1.22 FROM @N;
INSERT RigheOrdineFornitore(OrdineFornitoreId,ArticoloId,Quantita,PrezzoUnitario,ImportoNetto) SELECT n,n,20+n%40,25+n*3.75,(20+n%40)*(25+n*3.75) FROM @N;
INSERT DDTFornitori(NumeroDDT,DataDDT,FornitoreId,OrdineFornitoreId,VettoreId,TotaleQuantita) SELECT CONCAT('DDTF-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%200,'2026-09-01'),n,n,n,20+n%40 FROM @N;
INSERT RigheDDTFornitore(DDTFornitoreId,ArticoloId,Quantita) SELECT n,n,20+n%40 FROM @N;
INSERT FattureFornitori(NumeroFattura,DataFattura,FornitoreId,Imponibile,IVA,Totale,Stato) SELECT CONCAT('FF-2026-',FORMAT(n,'0000')),DATEADD(DAY,-n%180,'2026-09-01'),n,700+n*50,(700+n*50)*.22,(700+n*50)*1.22,CHOOSE((n-1)%3+1,'PAGATA','APERTA','PARZIALE') FROM @N;
INSERT RigheFatturaFornitore(FatturaFornitoreId,ArticoloId,AliquotaIVAId,Quantita,PrezzoUnitario,Imponibile) SELECT n,n,n,20+n%40,25+n*3.75,(20+n%40)*(25+n*3.75) FROM @N;
INSERT DistinteBase(Codice,ArticoloPadreId,Revisione,DataValidita,Stato) SELECT CONCAT('DB',FORMAT(n,'0000')),n,CONCAT('R',((n-1)%5)+1),DATEADD(DAY,-n%300,'2026-09-01'),'ATTIVA' FROM @N;
INSERT DistinteBaseRighe(DistintaBaseId,ArticoloComponenteId,Quantita,ScartoPercentuale) SELECT n,((n+9)%100)+1,1+n%8,n%4 FROM @N;
INSERT CicliProduzione(Codice,ArticoloId,Revisione,TempoAttrezzaggioMin,TempoCicloMin) SELECT CONCAT('CIC',FORMAT(n,'0000')),n,'R1',15+n%45,2+n%12 FROM @N;
INSERT FasiCiclo(CicloId,FaseNumero,Descrizione,RepartoId,CentroCostoId,TempoStandardMin) SELECT n,1,CHOOSE((n-1)%5+1,N'Taglio',N'Lavorazione CNC',N'Assemblaggio',N'Collaudo',N'Imballaggio'),n,n,10+n%40 FROM @N;
INSERT OrdiniProduzione(NumeroOrdine,ArticoloId,QuantitaPrevista,DataInizio,DataFinePrevista,Stato) SELECT CONCAT('OP-2026-',FORMAT(n,'0000')),n,100+n%300,DATEADD(DAY,-n%120,'2026-09-01'),DATEADD(DAY,10-n%5,'2026-09-01'),CHOOSE((n-1)%4+1,'PIANIFICATO','IN_LAVORAZIONE','COMPLETATO','SOSPESO') FROM @N;
INSERT AvanzamentiProduzione(OrdineProduzioneId,FaseNumero,DataRilevazione,DipendenteId,QuantitaBuona,QuantitaScarto,TempoMinuti) SELECT n,1,DATEADD(HOUR,n%2000,'2026-01-01'),n,90+n%200,n%12,60+n%180 FROM @N;
INSERT ControlliQualita(OrdineProduzioneId,ArticoloId,DataControllo,TipoControllo,Esito,ValoreMisurato,ValoreTarget) SELECT n,n,DATEADD(DAY,-n%180,'2026-09-01'),CHOOSE((n-1)%3+1,'DIMENSIONALE','VISIVO','FUNZIONALE'),CHOOSE((n-1)%10+1,'OK','OK','OK','OK','OK','OK','OK','OK','NON_CONFORME','OK'),50+n%10,55 FROM @N;
INSERT NonConformita(ControlloQualitaId,Codice,DataApertura,Gravita,Causa,CostoStimato,Stato) SELECT n,CONCAT('NC-',FORMAT(n,'0000')),DATEADD(DAY,-n%150,'2026-09-01'),CHOOSE((n-1)%3+1,'BASSA','MEDIA','ALTA'),CHOOSE((n-1)%4+1,N'Misura fuori tolleranza',N'Danneggiamento',N'Materiale non conforme',N'Errore processo'),250+n*17,CHOOSE((n-1)%3+1,'APERTO','IN_ANALISI','CHIUSO') FROM @N;
INSERT ContiContabili(Codice,Descrizione,TipoConto,ClasseBilancio) SELECT CONCAT('CON',FORMAT(n,'0000')),CHOOSE((n-1)%6+1,N'Cassa',N'Banca',N'Clienti',N'Fornitori',N'Ricavi',N'Costi'),CHOOSE((n-1)%2+1,'PATRIMONIALE','ECONOMICO'),CHOOSE((n-1)%2+1,'ATTIVO','PASSIVO') FROM @N;
INSERT MovimentiContabili(DataRegistrazione,ContoDareId,ContoAvereId,Documento,Descrizione,Importo,CentroCostoId) SELECT DATEADD(DAY,-n%300,'2026-09-01'),n,((n)%100)+1,CONCAT('REG-',FORMAT(n,'000000')),CONCAT(N'Registrazione contabile ',n),500+n*45,n FROM @N;
INSERT Scadenze(Tipo,Documento,ControparteId,DataScadenza,Importo,Stato) SELECT CHOOSE((n-1)%2+1,'CLIENTE','FORNITORE'),CONCAT('SCAD-',FORMAT(n,'000000')),n,DATEADD(DAY,n%120,'2026-09-01'),1000+n*60,CHOOSE((n-1)%3+1,'APERTO','PAGATO','SCADUTO') FROM @N;
INSERT IncassiPagamenti(Tipo,Documento,DataOperazione,Importo,BancaId,ScadenzaId) SELECT CHOOSE((n-1)%2+1,'INCASSO','PAGAMENTO'),CONCAT('MOVFIN-',FORMAT(n,'000000')),DATEADD(DAY,-n%120,'2026-09-01'),1000+n*60,n,n FROM @N;
INSERT Commesse(Codice,Descrizione,ClienteId,DataApertura,DataChiusura,Budget,Stato) SELECT CONCAT('COM-',FORMAT(n,'0000')),CONCAT(N'Commessa industriale ',n),n,DATEADD(DAY,-n%300,'2026-09-01'),DATEADD(DAY,30,'2026-09-01'),25000+n*900,CHOOSE((n-1)%3+1,'APERTA','IN_CORSO','CHIUSA') FROM @N;
INSERT AttivitaCommessa(CommessaId,DipendenteId,DataAttivita,Descrizione,Ore,CostoOrario) SELECT n,n,DATEADD(DAY,-n%90,'2026-09-01'),CHOOSE((n-1)%4+1,N'Analisi',N'Progettazione',N'Produzione',N'Collaudo'),2+n%7,25+n%25 FROM @N;
INSERT OpportunitaCRM(Codice,ClienteId,AgenteId,DataApertura,Fase,ValoreStimato,Probabilita) SELECT CONCAT('OPP-',FORMAT(n,'0000')),n,n,DATEADD(DAY,-n%180,'2026-09-01'),CHOOSE((n-1)%5+1,'LEAD','QUALIFICATA','PROPOSTA','NEGOZIAZIONE','VINTA'),5000+n*500,10+n%90 FROM @N;
INSERT InterazioniCRM(OpportunitaId,DataInterazione,Tipo,Oggetto,Esito,DipendenteId) SELECT n,DATEADD(DAY,-n%90,'2026-09-01'),CHOOSE((n-1)%4+1,'EMAIL','TELEFONO','MEETING','VISITA'),CONCAT(N'Follow-up opportunità ',n),CHOOSE((n-1)%3+1,N'Positivo',N'In attesa',N'Richiamare'),n FROM @N;
INSERT Budget(Codice,Anno,Descrizione,Stato) SELECT CONCAT('BUD-',n),2026,CONCAT(N'Budget aziendale ',n),CHOOSE((n-1)%3+1,'BOZZA','APPROVATO','CHIUSO') FROM @N;
INSERT BudgetRighe(BudgetId,CentroCostoId,ContoId,Mese,ImportoBudget,ImportoConsuntivo) SELECT n,n,n,((n-1)%12)+1,10000+n*250,8500+n*225 FROM @N;
INSERT AuditLog(Utente,Azione,TabellaNome,RecordId,ValorePrecedente,ValoreNuovo) SELECT CONCAT('utente',((n-1)%20)+1),CHOOSE((n-1)%3+1,'INSERT','UPDATE','DELETE'),CHOOSE((n-1)%6+1,'Clienti','Articoli','OrdiniClienti','FattureClienti','MovimentiMagazzino','Dipendenti'),n,N'valore precedente',N'valore nuovo' FROM @N;
GO
